// Generated from the scratchpad earnings/template.html. The page for /marketing/earnings (team only).
export const EARNINGS_PAGE = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<title>Earnings Calculator</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap\">\n<style>\n:root{\n  --bg:#000; --surface:#262220; --surface2:#161311; --line:rgba(249,248,247,0.10);\n  --fg:#F9F8F7; --muted:#B3ACA5; --faint:#8F8881; --fox:#F58220; --gold:#DBA44F; --green:#19C08C;\n  color-scheme:dark;\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;background:var(--bg);color:var(--fg)}\nbody{font-family:\"Poppins\",system-ui,sans-serif;font-size:15px;line-height:1.55}\n.wrap{max-width:1180px;margin:0 auto;padding:0 max(24px,env(safe-area-inset-left,0px))}\n@media (min-width:900px){.wrap{padding:0 56px}}\n.topbar{padding-top:40px}\n.brand{display:flex;align-items:center;gap:12px}\n.wm{height:30px;width:auto;display:block}\n.foxicon{width:44px;height:44px;display:block}\n.pill{font-size:11px;letter-spacing:.1em;text-transform:uppercase;padding:5px 10px;border-radius:999px;border:1px solid var(--line)}\n.crumb{margin-top:36px;font-size:13px;color:var(--faint)}\n.crumb a{color:var(--muted);text-decoration:none}\n.crumb a:hover{color:var(--fg)}\nheader{padding:20px 0 40px}\n.eyebrow{font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:var(--gold);display:flex;gap:10px;align-items:center;flex-wrap:wrap}\n.preview{font-size:10.5px;letter-spacing:.12em;padding:4px 10px;border-radius:999px;border:1px dashed rgba(219,164,79,.6);color:var(--gold)}\nh1{margin:16px 0 0;font-weight:700;font-size:clamp(36px,5.4vw,72px);line-height:1.02;letter-spacing:-.025em;max-width:16ch}\nh1 em{font-style:normal;color:var(--fox)}\n.lede{margin:22px 0 0;color:var(--muted);max-width:66ch;font-size:17px}\n\nform{display:flex;gap:10px;flex-wrap:wrap;margin:0 0 16px}\ninput{flex:1 1 420px;min-width:0;width:100%;min-height:60px;padding:0 22px;border-radius:16px;border:1px solid var(--line);background:var(--surface2);color:var(--fg);font:inherit;font-size:17px}\ninput::placeholder{color:var(--faint)}\ninput:focus{outline:2px solid var(--fox);outline-offset:1px}\n.go{min-height:60px;padding:0 30px;border-radius:16px;border:0;background:var(--fox);color:#000;font:inherit;font-weight:600;font-size:16px;cursor:pointer}\n.go:hover{filter:brightness(1.08)}\n.go[disabled]{opacity:.6;cursor:wait}\n.tries{font-size:13px;color:var(--faint)}\n.tries button{font:inherit;font-size:13px;color:var(--muted);background:none;border:0;border-bottom:1px dotted var(--faint);padding:0;margin:0 10px 0 4px;cursor:pointer}\n.err{margin-top:18px;padding:14px 18px;border-radius:12px;background:rgba(224,122,95,.12);border:1px solid rgba(224,122,95,.4);display:none}\n\n#out{display:none;padding:48px 0 24px}\n.chan{min-width:0;display:flex;gap:20px;align-items:center;flex-wrap:wrap;padding-bottom:32px;border-bottom:1px solid var(--line)}\n.chan img{width:72px;height:72px;border-radius:50%;background:var(--surface)}\n.chan h2{margin:0;font-size:26px;line-height:1.15}\n.chan .h{color:var(--muted);font-size:14px}\n.facts{display:flex;gap:24px 36px;flex-wrap:wrap;margin-left:auto}\n.facts div b{display:block;font-size:24px;font-weight:600;font-variant-numeric:tabular-nums;line-height:1.1}\n.facts div span{font-size:12.5px;color:var(--muted)}\n.bar{margin-top:20px;display:inline-flex;gap:8px;align-items:center;font-size:13px;padding:6px 12px;border-radius:999px}\n.bar.ok{background:rgba(25,192,140,.13);color:#5EE0B5}\n.bar.near{background:rgba(219,164,79,.14);color:#F0C77E}\n.bar.no{background:rgba(224,122,95,.14);color:#F2A08A}\n\n.grid{display:grid;grid-template-columns:minmax(0,1fr);gap:28px;margin-top:40px}\n@media (min-width:980px){.grid{grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:40px}}\n.card{padding:32px;border-radius:24px;background:var(--surface);border:1px solid var(--line)}\n.seg{display:flex;gap:6px;padding:5px;border-radius:14px;background:var(--surface2);border:1px solid var(--line)}\n.seg button{flex:1;min-height:42px;border-radius:10px;border:0;background:transparent;color:var(--muted);font:inherit;font-weight:500;font-size:14px;cursor:pointer}\n.seg button[aria-pressed=\"true\"]{background:var(--fox);color:#000}\n.seg button:hover:not([aria-pressed=\"true\"]){color:var(--fg)}\n.scen{margin:14px 0 0;font-size:13.5px;color:var(--muted);min-height:42px}\n.big{margin-top:28px}\n.big .lbl{font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:var(--gold)}\n.big b{display:block;margin-top:8px;font-size:clamp(48px,6vw,76px);font-weight:700;line-height:1;letter-spacing:-.02em;font-variant-numeric:tabular-nums}\n.big .yr{margin-top:10px;color:var(--muted);font-size:15px}\n.rows{margin-top:30px;border-top:1px solid var(--line)}\n.row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:4px 16px;padding:16px 0;border-bottom:1px solid var(--line)}\n.row .n{font-weight:600}\n.row .d{grid-column:1;font-size:13px;color:var(--muted)}\n.row .v{grid-row:1/3;grid-column:2;text-align:right;font-variant-numeric:tabular-nums;align-self:center}\n.row .v b{display:block;font-size:19px}\n.row .v span{font-size:12px;color:var(--faint)}\n.row.off{opacity:.45}\n.dft{margin-top:20px;font-size:13.5px;color:var(--muted)}\n\n.how h3{margin:0;font-size:20px}\n.how ol{margin:18px 0 0;padding-left:20px}\n.how li{margin:0 0 14px;color:#DDD6CF;font-size:14.5px}\n.how li b{color:var(--fg)}\n.how .src{margin-top:22px;padding-top:18px;border-top:1px solid var(--line);font-size:12.5px;color:var(--faint)}\n.vids{margin-top:24px}\n.vids h4{margin:0 0 10px;font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:var(--gold);font-weight:500}\n.vid{display:flex;justify-content:space-between;gap:16px;padding:8px 0;font-size:13.5px;border-bottom:1px solid var(--line)}\n.vid a{min-width:0;color:#DDD6CF;text-decoration:none;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.vid a:hover{color:var(--fg)}\n.vid span{color:var(--faint);white-space:nowrap;font-variant-numeric:tabular-nums}\n.next{margin:56px 0 96px;padding:28px 32px;border-radius:20px;border:1px dashed rgba(219,164,79,.5)}\n.next h3{margin:0;font-size:18px}\n.next p{margin:8px 0 0;color:var(--muted);font-size:14.5px;max-width:80ch}\n.empty{padding:40px 0 96px;color:var(--faint);font-size:14px}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <div class=\"topbar\"><div class=\"brand\"><img class=\"foxicon\" alt=\"\" src=\"data:image/svg+xml;base64,\"><svg role=\"img\" aria-label=\"Digital Fox\" class=\"wm\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"52.80 20.06 191.15 55.43\"><path d=\"M53.82,36.27h10.33c5.57,0,9.17,1.02,9.17,8.15v17.55c0,4.77-3.65,6.1-7.26,6.1H53.82V36.27z M62.02,62.72h1.2 c1.2,0,1.96-1.11,1.92-2.63V44.24c0.04-1.51-0.71-2.63-1.92-2.63h-1.2V62.72z\" fill=\"#FFFFFF\"/><path d=\"M75.16,36.27h8.19v31.8h-8.19V36.27z\" fill=\"#FFFFFF\"/><path d=\"M104.68,68.07h-5.34l-0.62-2.23c-1.42,1.96-3.83,2.89-6.19,2.89c-5.61,0-7.35-4.54-7.35-9.26V45.44 c0-5.03,1.51-9.84,9.75-9.84c6.95,0,9.49,2.63,9.49,9.13v3.25h-8.19v-4.9c0-1.25-0.18-2.14-1.29-2.14c-1.38,0-1.56,1.25-1.56,2.36 v17.46c0,1.38,0.36,2.49,1.56,2.49c1.47,0,1.56-1.2,1.56-2.45v-5.34h-1.69v-4.54h9.89V68.07z\" fill=\"#FFFFFF\"/><path d=\"M106.5,36.27h8.19v31.8h-8.19V36.27z\" fill=\"#FFFFFF\"/><path d=\"M121.38,42.68h-4.85v-6.41h17.9v6.41h-4.85v25.38h-8.19V42.68z\" fill=\"#FFFFFF\"/><path d=\"M136.29,36.27h11.8l4.36,31.8h-8.19l-0.4-5.61h-2.98l-0.4,5.61h-8.19L136.29,36.27z M143.73,56.85l-1.42-14.96h-0.09 l-1.34,14.96H143.73z\" fill=\"#FFFFFF\"/><path d=\"M153.66,36.27h8.19v25.65h5.43v6.15h-13.63V36.27z\" fill=\"#FFFFFF\"/><path d=\"M242.89,48.67c-0.18-1.99-1.49-2.25-2.26-2.21c0,0-0.56,0.03-0.88,0.45c-0.14,0.18-0.27,0.53-0.31,0.78 c-0.36,2.25-1.68,7.56-6.11,8.19c-1.51,0.21-2.77-0.46-4.02-2.17l0.18-0.26c3.71-5.23,7.21-10.17,8.67-13.26l0.05-0.12 c0.23-0.65,0.34-1.16,0.45-1.78l0.01-0.12c0.6-4.06-4.37-5.22-4.37-5.22s0.16,0.52-0.17,1.53c-0.51,1.55-3.77,7.65-7.48,13.56 c-0.47-1.32-0.9-2.67-1.3-3.92c-0.22-0.69-0.43-1.36-0.65-1.99c-1.38-3.82-3.71-4.26-7.79-3.75l-1.33,0.17l0.25,1.31 c0.05,0.25,0.8,4.08,2.22,8.66c-0.84,1.89-2.11,4.04-3.64,4.81c0.2-1.83,0.22-3.55,0.1-5.15c-0.11-1.4-0.43-4.19-1.24-5.19 c-0.53-0.65-1.04-0.35-1.21-0.36c-1.35-3.01-4.17-4.5-7.72-4c-4.39,0.62-7.56,4.47-9.39,9.12c-0.64-2.47-1.6-4.27-6.54-3.58 c-1.16,0.16-2.61,0.4-4.2,0.7c0.65-4.2,2.06-10.84,2.06-10.9c5.52-1.4,10.76-2.67,14.91-3.25c5.24-0.74,6.97-0.02,7.59,0.41 c1.46,1.02,0.68,4.01,0.68,4.01l1.97-2.56c2.49-3.24,3.2-6.34,1.94-8.51c-1.59-2.73-5.79-3.58-12.82-2.59 c-8.03,1.13-18.43,4.08-27.6,6.68c-1.4,0.4-2.77,0.78-4.07,1.15c0.03-0.14,0.04-0.3,0.03-0.47c-0.04-0.45-0.26-0.86-0.63-1.15 c-1.37-1.09-5.56-0.57-6.39-0.45c-4.42,0.62-10.88,3.09-10.52,7.34c0.11,1.33,0.67,2.41,1.67,3.2c2,1.6,5.66,1.96,11.53,1.13 c4.67-0.66,10.31-1.98,15.5-3.28c-0.61,2.37-1.58,6.2-2.57,10.51c-4.41,0.8-8.32,1.58-8.36,1.58l-1.28,0.25l0.3,1.27 c0.03,0.12,0.75,3.04,3.38,4.5c0.9,0.54,2.2,0.7,4.16,0.49c-1.42,7.07-2.03,12.01-1.8,14.7c0.14,1.74,0.86,3.17,2.06,4.13 c1.44,1.15,3.19,1.38,4.38,1.38c0.52,0,0.93-0.04,1.16-0.08c1.46-0.21,2.6-0.95,2.05-2.49c-0.31-0.85-0.67-2.26-0.81-3.92 c-0.3-3.62-0.13-9.05,0.46-15c2.34-0.45,8.5-1.66,10.81-2.33c-0.78,2.93-1.08,5.96-0.86,8.58c0.31,3.78,1.6,6.67,3.73,8.37 c1.35,1.08,2.97,1.63,4.82,1.63c0.47,0,0.95-0.03,1.45-0.1c4.54-0.64,8.18-4.31,10.08-10.12c3.19-0.47,5.38-2.45,6.78-4.96 c0.29,0.7,0.59,1.4,0.91,2.08c-3.22,4.34-5.66,7.87-5.99,10.38c-0.39,4.14,4.98,6.15,4.98,6.15s-0.08-0.82,0.16-2.31 c0.34-2.08,1.45-4.64,4.04-8.79c2.65,3.39,5.21,3.89,6.99,3.63C239.54,63.95,243.28,52.91,242.89,48.67z M204.13,62.18 c-0.49,0.07-0.88-0.02-1.22-0.29c-0.74-0.59-1.25-2-1.4-3.87c-0.48-5.82,2.67-14.07,5.54-14.47c0.02,0,0.03,0,0.05,0 c0.31,0,0.53,0.41,0.67,0.78c-1.34,1.74-2.05,4.63-1.82,7.5c0.21,2.51,1.06,4.53,2.42,5.79 C207.17,60.45,205.78,61.95,204.13,62.18z\" fill=\"#F58220\"/></svg><span class=\"pill\">Ecosystem</span><a href=\"/auth/logout\" style=\"margin-left:auto;white-space:nowrap;font-size:14px;color:var(--muted);text-decoration:none;padding:12px 0\">Sign out</a></div></div>\n  <div class=\"crumb\"><a href=\"/\">Ecosystem</a> / <a href=\"/marketing\">Marketing and Website</a> / Earnings calculator</div>\n  <header>\n    <div class=\"eyebrow\">Marketing <span class=\"preview\">Internal preview</span></div>\n    <h1>What could DFT earn <em>this channel?</em></h1>\n    <p class=\"lede\">Enter any YouTube channel. We read its recent long-form videos and estimate what the creator would take home each month with DFT, from what our roster actually earns on brand deals and platforms.</p>\n  </header>\n\n  <form id=\"f\" autocomplete=\"off\">\n    <input id=\"q\" name=\"q\" placeholder=\"@handle or youtube.com link\" aria-label=\"YouTube channel\" required>\n    <button class=\"go\" id=\"go\" type=\"submit\">Estimate</button>\n  </form>\n  <div class=\"tries\">Try a roster channel: <button type=\"button\" data-q=\"@heavyspoilers\">Heavy Spoilers</button><button type=\"button\" data-q=\"@TheCosmicWonder\">Cosmic Wonder</button><button type=\"button\" data-q=\"@geekdom101\">Geekdom101</button></div>\n  <div class=\"err\" id=\"err\" role=\"alert\"></div>\n\n  <section id=\"out\" aria-live=\"polite\">\n    <div class=\"chan\">\n      <img id=\"cThumb\" alt=\"\">\n      <div>\n        <h2 id=\"cName\"></h2>\n        <div class=\"h\" id=\"cHandle\"></div>\n      </div>\n      <div class=\"facts\">\n        <div><b id=\"cAvg\"></b><span>avg views, last 10 long-form</span></div>\n        <div><b id=\"cPer\"></b><span>long-form uploads a month</span></div>\n        <div><b id=\"cSubs\"></b><span>subscribers</span></div>\n      </div>\n    </div>\n    <div id=\"cBar\" class=\"bar\"></div>\n\n    <div class=\"grid\">\n      <div class=\"card\">\n        <div class=\"seg\" role=\"group\" aria-label=\"Scenario\">\n          <button data-s=\"0\" aria-pressed=\"true\">Typical</button>\n          <button data-s=\"1\" aria-pressed=\"false\">Strong</button>\n          <button data-s=\"2\" aria-pressed=\"false\">Top</button>\n        </div>\n        <p class=\"scen\" id=\"scen\"></p>\n        <div class=\"big\">\n          <div class=\"lbl\">To the creator, each month</div>\n          <b id=\"total\"></b>\n          <div class=\"yr\" id=\"year\"></div>\n        </div>\n        <div class=\"rows\" id=\"rows\"></div>\n        <p class=\"dft\" id=\"dftLine\"></p>\n      </div>\n\n      <div class=\"card how\">\n        <h3>How it is worked out</h3>\n        <ol>\n          <li><b>Brand deals.</b> Our list rate is the roster formula: 1.5 times average views as the guarantee, at a $25 CPM, with a $1,500 minimum. Across 26 roster channels over the last year, deals closed at a median <span id=\"mAch\"></span> of list. The creator keeps <span id=\"mShare\"></span> of each deal.</li>\n          <li><b>How often deals land.</b> Typical is the median roster channel posting 4 or more videos a month (<span id=\"mD0\"></span> deals a month), Strong is the top 30% (<span id=\"mD1\"></span>) and Top is the top 20% (<span id=\"mD2\"></span>). Never more deals than uploads.</li>\n          <li><b>Platforms.</b> What roster creators earn a month on each platform DFT runs for them (August 2026 statements, typical, strong and top). These are not yet scaled to channel size. The creator receives 60% after DFT's first $50 on each platform.</li>\n        </ol>\n        <div class=\"vids\" id=\"vids\"></div>\n        <div class=\"src\">Sources: US Campaigns (454 campaigns, Oct 2025 to Oct 2026), Rates board, Platform Creator Payments. Channel numbers are read live from YouTube.</div>\n      </div>\n    </div>\n\n    <div class=\"next\">\n      <h3>Before this goes public</h3>\n      <p>The public version on digitalfoxtalent.com would show one rounded range rather than three scenarios, ask for an email to see the breakdown, and save every result to Creator Applications as a lead, with channels under our 50k bar getting a polite not yet. Platform figures should be scaled to channel size first.</p>\n    </div>\n  </section>\n  <div class=\"empty\" id=\"empty\">Results appear here.</div>\n</div>\n\n<script>\n// THE MODEL. Every number below comes from DFT's own boards (see the \"How it is worked out\" panel).\nconst MODEL={\n  cpm:25, guaranteeX:1.5, floor:1500,          // roster list rate (Rates - View Guarantee Model)\n  achieved:0.57,                               // median closed price vs list, 26 roster channels, Oct 2025 to Oct 2026\n  creatorShare:0.70,                           // median creator cost / gross, 454 campaigns\n  deals:[0.4,1,2],                             // deals a month: median, top 30%, top 20% of roster channels posting 4+ a month\n  bar:50000, near:30000,                       // sign-up bar on long-form average (dft-connect QUALIFY / NEAR)\n  platformFee:50, platformShare:0.60,          // standard platform terms: DFT keeps the first $50, creator 60% of the rest\n  platforms:[                                  // gross a month per creator, Aug 2026 statements: typical, strong, top\n    {name:\"MSN video\", what:\"Videos and Shorts syndicated to MSN\", v:[197,360,1559]},\n    {name:\"Facebook\", what:\"Back catalogue published to a creator page\", v:[266,515,1002]},\n    {name:\"Video podcast\", what:\"Episodes on Spotify Video through Megaphone\", v:[140,220,535]}\n  ]\n};\nconst SCEN=[\"The median roster channel: about one brand deal every couple of months, and middle-of-the-pack platform earnings.\",\"A channel in our top third: around one brand deal a month, and upper-quartile platform earnings.\",\"One of our best performers: two or more deals a month, and top-of-roster platform earnings.\"];\nconst $=id=>document.getElementById(id);\nconst usd=n=>\"$\"+Math.round(n).toLocaleString(\"en-US\");\nconst short=n=>n>=1e6?(n/1e6).toFixed(n>=1e7?0:1)+\"m\":n>=1e3?Math.round(n/1e3)+\"k\":String(n);\nlet ch=null,sc=0;\n$(\"mAch\").textContent=Math.round(MODEL.achieved*100)+\"%\";\n$(\"mShare\").textContent=Math.round(MODEL.creatorShare*100)+\"%\";\nMODEL.deals.forEach((d,i)=>$(\"mD\"+i).textContent=d);\n\nfunction listRate(avg){return Math.max(MODEL.floor,MODEL.guaranteeX*avg/1000*MODEL.cpm);}\nfunction render(){\n  if(!ch)return;\n  const rate=listRate(ch.avg), deal=rate*MODEL.achieved;\n  const n=Math.min(MODEL.deals[sc], ch.perMonth||0);\n  const brandGross=n*deal, brandCreator=brandGross*MODEL.creatorShare;\n  let rows=`<div class=\"row${n?\"\":\" off\"}\"><div class=\"n\">Brand deals</div><div class=\"d\">${n?`${n<1?Math.round(n*12)+\" a year\":n+\" a month\"} at about ${usd(deal)} each (list ${usd(rate)}). Creator keeps ${Math.round(MODEL.creatorShare*100)}%.`:\"No recent long-form uploads to sell against.\"}</div><div class=\"v\"><b>${usd(brandCreator)}</b><span>of ${usd(brandGross)} gross</span></div></div>`;\n  let total=brandCreator, gross=brandGross;\n  MODEL.platforms.forEach(p=>{\n    const g=p.v[sc], c=Math.max(0,g-MODEL.platformFee)*MODEL.platformShare;\n    total+=c; gross+=g;\n    rows+=`<div class=\"row\"><div class=\"n\">${p.name}</div><div class=\"d\">${p.what}</div><div class=\"v\"><b>${usd(c)}</b><span>of ${usd(g)} gross</span></div></div>`;\n  });\n  $(\"rows\").innerHTML=rows;\n  $(\"total\").textContent=usd(total);\n  $(\"year\").textContent=usd(total*12)+\" a year, from \"+usd(gross)+\" a month gross\";\n  $(\"dftLine\").textContent=\"DFT's share: about \"+usd(gross-total)+\" a month, \"+usd((gross-total)*12)+\" a year.\";\n  $(\"scen\").textContent=SCEN[sc];\n  document.querySelectorAll(\".seg button\").forEach(b=>b.setAttribute(\"aria-pressed\",String(+b.dataset.s===sc)));\n}\nfunction show(d){\n  ch=d;\n  $(\"cThumb\").src=d.thumb||\"\";\n  $(\"cName\").textContent=d.title;\n  $(\"cHandle\").innerHTML=(d.handle?d.handle+\" \u00b7 \":\"\")+`<a href=\"https://www.youtube.com/channel/${d.id}\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--muted)\">Open on YouTube</a>`+(d.searched?\" \u00b7 matched by search, check it is the right channel\":\"\")+(d.source===\"roster\"?\" \u00b7 YouTube lookups are paused for today, so these numbers come from the roster's Rates board\":\"\");\n  $(\"cThumb\").style.display=d.thumb?\"\":\"none\";\n  $(\"cAvg\").textContent=d.avg?short(d.avg):\"None\";\n  $(\"cPer\").textContent=d.perMonth;\n  $(\"cSubs\").textContent=d.hiddenSubs?\"Hidden\":short(d.subs);\n  const bar=$(\"cBar\");\n  if(d.avg>=MODEL.bar){bar.className=\"bar ok\";bar.textContent=\"Meets our 50k sign-up bar\";}\n  else if(d.avg>=MODEL.near){bar.className=\"bar near\";bar.textContent=\"Between 30k and 50k: only with a referral\";}\n  else{bar.className=\"bar no\";bar.textContent=\"Under 30k: below our sign-up bar today\";}\n  $(\"vids\").innerHTML=d.recent&&d.recent.length?`<h4>Videos the average is based on</h4>`+d.recent.map(v=>`<div class=\"vid\"><a href=\"https://www.youtube.com/watch?v=${v.id}\" target=\"_blank\" rel=\"noopener\">${v.title.replace(/[<>&]/g,c=>({\"<\":\"&lt;\",\">\":\"&gt;\",\"&\":\"&amp;\"}[c]))}</a><span>${short(v.views)}</span></div>`).join(\"\")+(d.basis>5?`<div class=\"vid\"><span>and ${d.basis-5} more</span><span></span></div>`:\"\"):\"\";\n  $(\"out\").style.display=\"block\"; $(\"empty\").style.display=\"none\";\n  render();\n}\nasync function look(q){\n  $(\"err\").style.display=\"none\"; $(\"go\").disabled=true; $(\"go\").textContent=\"Reading channel\";\n  try{\n    const r=await fetch(\"/earnings-data?ch=\"+encodeURIComponent(q),{credentials:\"same-origin\"});\n    const j=await r.json();\n    if(!r.ok||j.error)throw new Error(j.error||\"Lookup failed\");\n    show(j);\n    try{history.replaceState(null,\"\",\"?ch=\"+encodeURIComponent(q));}catch(e){}\n  }catch(e){$(\"err\").textContent=e.message;$(\"err\").style.display=\"block\";}\n  finally{$(\"go\").disabled=false;$(\"go\").textContent=\"Estimate\";}\n}\n$(\"f\").addEventListener(\"submit\",e=>{e.preventDefault();look($(\"q\").value);});\ndocument.querySelector(\".tries\").addEventListener(\"click\",e=>{const b=e.target.closest(\"button\");if(!b)return;$(\"q\").value=b.dataset.q;look(b.dataset.q);});\ndocument.querySelector(\".seg\").addEventListener(\"click\",e=>{const b=e.target.closest(\"button\");if(!b)return;sc=+b.dataset.s;render();});\nconst q0=new URLSearchParams(location.search).get(\"ch\"); if(q0){$(\"q\").value=q0;look(q0);}\n</script>\n</body>\n</html>\n";
